  // "ℹ️ La calificación de cumplimiento (85.0%) se calcula exclusivamente sobre los controles mandatorios para el Nivel L2. Los requisitos de niveles superiores evaluados se presentan como recomendaciones técnicas avanzadas sin penalizar la calificación de este nivel."
